                                    // address-book eviction (the async block moves them).
                                    let addrbook = std::sync::Arc::clone(&addrbook_for_hook);
                                    let addrbook_dirty = addrbook_dirty_for_hook.clone();
                                    let projection_registry =
                                        std::sync::Arc::clone(&community_registry_for_heal);
                                    // ZEB-495: per-invocation clones for the
                                    // self-introduce trigger (async block moves
                                    // them).
                                    let device_intro_doc = device_intro_doc.clone();
                                    let device_intro_engine = device_intro_engine.clone();
                                    let device_intro_signing_key =
                                        std::sync::Arc::clone(&device_intro_signing_key);
                                    let device_intro_cert = device_intro_cert.clone();
                                    let device_intro_hlc_tracker =
                                        std::sync::Arc::clone(&device_intro_hlc_tracker);
                                    let device_intro_adopt_floor = device_intro_adopt_floor.clone();
                                    let device_intro_device_id = device_intro_device_id.clone();
                                    let device_intro_registry =
                                        std::sync::Arc::clone(&device_intro_registry);
                                    let device_intro_done =
                                        std::sync::Arc::clone(&device_intro_done);
                                    // ZEB-568: per-invocation clone of the eager
                                    // profile-card republish sender (async block
                                    // moves it; mirrors the other per-invocation
                                    // hook clones above).
