// ── Mail commands ────────────────────────────────────────────────────────

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SendMailPayload {
    to: Vec<String>,
    subject: String,
    body: String,
    reply_to: Option<String>,
}

#[tauri::command]
async fn send_mail(
    payload: SendMailPayload,
    state: tauri::State<'_, Mutex<NodeState>>,
) -> Result<(), String> {
    use harmony_mailbox::message::{
        unique_message_id, HarmonyMessage, MailMessageType, MessageFlags, Recipient, RecipientType,
    };

    if payload.to.is_empty() {
        return Err("at least one recipient required".to_string());
    }
    if payload.subject.is_empty() && payload.body.is_empty() {
        return Err("subject or body required".to_string());
    }

    let (publish_tx, node_addr, mail_mgr) = {
        let guard = state.lock().map_err(|e| format!("lock: {e}"))?;
        let tx = guard
            .publish_tx
            .clone()
            .ok_or_else(|| "not connected".to_string())?;
        let mgr = guard
            .mail_mgr
            .clone()
            .ok_or_else(|| "mail not initialized".to_string())?;
        (tx, guard.node_addr.clone(), mgr)
    };

    // Parse sender address
    let sender_bytes: [u8; 16] = hex::decode(&node_addr)
        .map_err(|e| format!("bad node_addr: {e}"))?
        .try_into()
        .map_err(|_| "node_addr not 16 bytes".to_string())?;

    // Parse in_reply_to
    let in_reply_to = match &payload.reply_to {
        Some(hex_str) if !hex_str.is_empty() => {
            let bytes = hex::decode(hex_str).map_err(|e| format!("bad reply_to: {e}"))?;
            let arr: [u8; 16] = bytes
                .try_into()
                .map_err(|_| "reply_to not 16 bytes".to_string())?;
            Some(arr)
        }
        _ => None,
    };

    // Parse recipients
    let recipients: Vec<Recipient> = payload
        .to
        .iter()
        .map(|addr_hex| {
            let bytes =
                hex::decode(addr_hex).map_err(|e| format!("bad recipient {addr_hex}: {e}"))?;
            let arr: [u8; 16] = bytes
                .try_into()
                .map_err(|_| format!("recipient {addr_hex} not 16 bytes"))?;
            Ok(Recipient {
                address_hash: arr,
                recipient_type: RecipientType::To,
            })
        })
        .collect::<Result<Vec<_>, String>>()?;

    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    let is_reply = in_reply_to.is_some();
    let msg = HarmonyMessage {
        version: 0x01,
        message_type: MailMessageType::Email,
        flags: MessageFlags::new(false, is_reply, false),
        timestamp: now,
        message_id: unique_message_id(),
        in_reply_to,
        sender_address: sender_bytes,
        recipients,
        subject: payload.subject,
        body: payload.body,
        attachments: vec![],
    };

    let msg_bytes = msg.to_bytes().map_err(|e| format!("serialize: {e}"))?;

    // Publish to each recipient's Zenoh key (canonical lowercase hex)
    for recipient in &msg.recipients {
        let key_expr = format!("harmony/mail/v1/{}", hex::encode(recipient.address_hash));
        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
        publish_tx
            .send(event_loop::PublishRequest {
                key_expr,
                payload: msg_bytes.clone(),
                reply: reply_tx,
            })
            .await
            .map_err(|_| "event loop not running".to_string())?;
        reply_rx
            .await
            .map_err(|_| "event loop dropped request".to_string())??;
    }

    // Store in sent folder only after all publishes succeed
    {
        let mut mgr = mail_mgr.lock().map_err(|e| format!("mail lock: {e}"))?;
        mgr.store_sent(&msg_bytes, &msg)?;
    }

    Ok(())
}

#[tauri::command]
fn list_mail(
    folder: String,
    page: usize,
    per_page: usize,
    state: tauri::State<'_, Mutex<NodeState>>,
) -> Result<Vec<mail::EntryRecord>, String> {
    let mgr_arc = {
        let guard = state.lock().map_err(|e| format!("lock: {e}"))?;
        guard
            .mail_mgr
            .clone()
            .ok_or_else(|| "mail not initialized".to_string())?
    }; // NodeState lock dropped — disk I/O below doesn't block other commands
    let mgr = mgr_arc.lock().map_err(|e| format!("mail lock: {e}"))?;
    Ok(mgr.list_folder(&folder, page, per_page))
}

#[tauri::command]
fn get_mail(
    message_cid: String,
    state: tauri::State<'_, Mutex<NodeState>>,
) -> Result<mail::MailDetail, String> {
    let mgr_arc = {
        let guard = state.lock().map_err(|e| format!("lock: {e}"))?;
        guard
            .mail_mgr
            .clone()
            .ok_or_else(|| "mail not initialized".to_string())?
    };
    let mgr = mgr_arc.lock().map_err(|e| format!("mail lock: {e}"))?;

    // Targeted O(N) scan by reference (no folder clone): only the matching
    // entry is read, even on a 10k-message inbox. If Pending, return a
    // stub MailDetail — the blob doesn't exist on disk yet, so
    // mgr.get_message would fail. Frontend recognizes body_state=Pending
    // and triggers fetch_mail_body.
    if let Some(entry) = mgr.entry_by_cid(&message_cid) {
        if entry.body_state == mail::BodyState::Pending {
            return Ok(mail::MailDetail {
                message_cid: message_cid.clone(),
                message_id: entry.message_id.clone(),
                subject: entry.subject_snippet.clone(),
                body: String::new(),
                sender_address: entry.sender_address.clone(),
                recipients: vec![],
                timestamp: entry.timestamp,
                attachments: vec![],
                is_reply: false,
                is_forward: false,
                in_reply_to: None,
                body_state: mail::BodyState::Pending,
            });
        }
    }

    // Local (or entry missing — let get_message produce the proper error).
    mgr.get_message(&message_cid)
}

#[tauri::command]
async fn refresh_mail(state: tauri::State<'_, Mutex<NodeState>>) -> Result<(), String> {
    let sync_arc = {
        let guard = state.lock().map_err(|e| format!("lock: {e}"))?;
        guard
            .mail_sync
            .clone()
            .ok_or_else(|| "mail_sync not initialized".to_string())?
    };
    sync_arc.refresh_now().await;
    Ok(())
}

#[tauri::command]
async fn fetch_mail_body(
    message_cid: String,
    state: tauri::State<'_, Mutex<NodeState>>,
) -> Result<mail::MailDetail, String> {
    let (sync_arc, mgr_arc) = {
        let guard = state.lock().map_err(|e| format!("lock: {e}"))?;
        let sync = guard
            .mail_sync
            .clone()
            .ok_or_else(|| "mail_sync not initialized".to_string())?;
        let mgr = guard
            .mail_mgr
            .clone()
            .ok_or_else(|| "mail not initialized".to_string())?;
        (sync, mgr)
    };

    // Decode CID hex → 32-byte array.
    let cid_bytes = hex::decode(&message_cid).map_err(|e| format!("bad cid hex: {e}"))?;
    let cid_arr: [u8; 32] = cid_bytes
        .try_into()
        .map_err(|_| "cid must be 32 bytes".to_string())?;

    // Trigger lazy fetch (no-op if already Local; writes blob + promotes entry).
    sync_arc.fetch_body(cid_arr).await?;

    // Now return the fully-Local MailDetail from the manager.
    let mgr = mgr_arc.lock().map_err(|e| format!("mail lock: {e}"))?;
    mgr.get_message(&message_cid)
}

#[tauri::command]
fn update_mail(
    message_cid: String,
    action: String,
    folder: Option<String>,
    state: tauri::State<'_, Mutex<NodeState>>,
) -> Result<(), String> {
    let mgr_arc = {
        let guard = state.lock().map_err(|e| format!("lock: {e}"))?;
        guard
            .mail_mgr
            .clone()
            .ok_or_else(|| "mail not initialized".to_string())?
    };
    let mut mgr = mgr_arc.lock().map_err(|e| format!("mail lock: {e}"))?;
    let folder_ref = folder.as_deref();
    match action.as_str() {
        "mark_read" => mgr.mark_read(&message_cid, true, folder_ref),
        "mark_unread" => mgr.mark_read(&message_cid, false, folder_ref),
        "move_trash" => mgr.move_message(&message_cid, folder_ref, "trash"),
        "move_inbox" => mgr.move_message(&message_cid, folder_ref, "inbox"),
        "delete" => mgr.delete_message(&message_cid, folder_ref),
        _ => Err(format!("unknown action: {action}")),
    }
}

#[tauri::command]
fn get_mail_counts(
    state: tauri::State<'_, Mutex<NodeState>>,
) -> Result<std::collections::HashMap<String, mail::FolderCounts>, String> {
    let mgr_arc = {
        let guard = state.lock().map_err(|e| format!("lock: {e}"))?;
        guard
            .mail_mgr
            .clone()
            .ok_or_else(|| "mail not initialized".to_string())?
    };
    let mgr = mgr_arc.lock().map_err(|e| format!("mail lock: {e}"))?;
    Ok(mgr.folder_counts())
}

// ── E2E test helpers (debug builds only) ────────────────────────────────

/// Close a child window by label. Used by the Playwright E2E suite to reset
/// the network-viz window between runs — without this, a leftover viz from
/// the previous run makes the ZEB-144 "Open network visualization" regression
/// guard pass vacuously on reruns.
///
/// Restricted to the `network-viz` label so a stray dev-build IPC call can't
/// take down the main window. Stripped from release binaries entirely via
/// `#[cfg(debug_assertions)]` and the matching conditional registration in
/// `run()` below.
#[cfg(debug_assertions)]
#[tauri::command]
async fn e2e_close_window(app: AppHandle, label: String) -> Result<(), String> {
    use tauri::Manager;
    if label != "network-viz" {
        return Err(format!("e2e_close_window: label '{label}' not allowed"));
    }
    if let Some(window) = app.get_webview_window(&label) {
        window.close().map_err(|e| e.to_string())?;
    }
    Ok(())
}

// ── CLI entry points ─────────────────────────────────────────────────────

/// CLI entry point for `harmony-app rotate-passphrase`.
///
/// Refusal conditions (in order):
///   1. OS keychain has an identity → refuse with explanation
///   2. HARMONY_PASSPHRASE / HARMONY_PASSPHRASE_FILE not set → refuse
///   3. --new-passphrase-file unreadable / empty → refuse
///   4. New passphrase byte-identical to old → log warning, proceed
///
/// Returns Ok(()) on successful rotation; Err on any refusal or rotation
/// failure. Caller (main.rs) translates Err into a non-zero exit.
pub fn rotate_passphrase_cli(new_passphrase_file: &std::path::Path) -> Result<(), String> {
    use identity::KeyStore as _;
    use secrecy::SecretString;

    // Refusal 1: keychain has identity, or its state can't be determined.
    // Failing closed on load() Err is important — if we can't tell whether the
    // identity is in the keychain, we must NOT rotate the encrypted file
    // (the rotation would silently target the wrong backend).
    //
    // KeychainStore::new() Err is trickier. The strict-correct posture is to
    // also fail closed, but that breaks the legitimate headless case (Linux
    // server with no Secret Service / no D-Bus session — the entire point of
    // the encrypted-file backend). The keyring crate's error type doesn't
    // cleanly distinguish "no backend on this system" from "backend present
    // but transiently unreachable", so we can't auto-discriminate. Compromise:
    // log a loud warning on new() Err so an operator on a misconfigured
    // desktop sees a signal, and proceed (the typical headless case is
    // benign). Operators with both a populated OS keychain and an .enc file
    // who hit a transient keychain failure mid-rotation could rotate the
    // wrong backend; this is a known niche risk documented here.
    match identity::KeychainStore::new() {
        Ok(kc) => match kc.load() {
            Ok(Some(_)) => {
                return Err(
                    "your identity is currently in the OS keychain; passphrase rotation only applies to headless installs. \
                     Re-encryption of keychain entries is handled by the OS when you change your login password.".to_string(),
                );
            }
            Ok(None) => {
                // Keychain reachable and empty → safe to rotate the .enc backend.
            }
            Err(e) => {
                return Err(format!(
                    "could not determine whether the identity is stored in the OS keychain — refusing to rotate to avoid acting on the wrong backend: {e}"
                ));
            }
        },
        Err(e) => {
            tracing::warn!(
                "OS keychain backend unavailable ({e}); proceeding with encrypted-file \
                 rotation. If you have a desktop install where the keychain SHOULD be \
                 reachable, this may indicate a transient or configuration issue and the \
                 rotation could affect a different backend than your active identity. \
                 On a headless install (typical case for this command) this is expected."
            );
        }
    }

    // Resolve old passphrase via the standard env chain.
    let identity_path = identity::resolve_path(None)?;
    let enc_path = identity_path.with_file_name("identity.enc");
    let old_store = identity::EncryptedFileStore::from_env(enc_path)?
        .ok_or_else(|| {
            "HARMONY_PASSPHRASE / HARMONY_PASSPHRASE_FILE not set — cannot rotate without the old passphrase".to_string()
        })?;

    // Read the new passphrase file via the same parser as HARMONY_PASSPHRASE_FILE
    // — UTF-8, exactly one trailing newline strip, empty rejection, AND the
    // 0600-mode warning the inline version was missing.
    let new_str = identity::parse_passphrase_file(new_passphrase_file).map_err(|e| {
        format!(
            "--new-passphrase-file={} {e}",
            new_passphrase_file.display()
        )
    })?;

    // Move into SecretString immediately so the plaintext String is consumed
    // (no second copy lingers on the heap unzeroed). passphrase_eq takes a
    // borrow, then rotate_passphrase moves the SecretString through.
    let candidate = SecretString::from(new_str);
    if old_store.passphrase_eq(&candidate) {
        tracing::warn!("new passphrase matches old — proceeding anyway");
    }

    // Rotate.
    identity::rotate_passphrase(&old_store, candidate)?;
    Ok(())
}

/// ZEB-519: run a CLI entry point's body on a dedicated 8 MiB-stack thread and
/// return its process exit code.
///
/// Tokio's `Runtime::block_on` drives its *root* future on the CALLING thread
/// (only `tokio::spawn`ed tasks go to workers). On Windows/MSVC the OS main
/// thread's stack is fixed at link time by the `/STACK` linker arg and is NOT
/// sized by `RUST_MIN_STACK` (which only reaches std-spawned threads); a
/// repo-root cargo build that misses `src-tauri/.cargo/config.toml` links the
/// ~1 MiB MSVC default and overflows on `serve` boot. Driving CLI entries on a
/// thread we size ourselves removes the dependency on the link-time `/STACK`
/// value on every platform. Mirrors the `harmony-runtime` GUI path above.
///
/// The panic → exit-1 contract assumes `panic = "unwind"` (the default) so
/// `join()` observes the panic. Under `panic = "abort"` a panicking entry would
/// `SIGABRT` the process instead — acceptable (still non-zero), but the code
/// path here would not run.
pub fn run_on_large_stack<F>(name: &str, f: F) -> i32
where
    F: FnOnce() -> i32 + Send + 'static,
{
    match thread::Builder::new()
        .name(name.to_string())
        .stack_size(8 * 1024 * 1024)
        .spawn(f)
    {
        Ok(h) => h.join().unwrap_or_else(|_| {
            // The default panic hook already printed the payload + backtrace to
            // stderr before unwinding. Exit non-zero so a supervisor never
            // mistakes a serve crash for a clean (exit 0) shutdown.
            eprintln!("harmony-app: {name} thread panicked");
            1
        }),
        Err(e) => {
            eprintln!("harmony-app: cannot spawn {name} thread: {e}");
            1
        }
    }
}

#[cfg(test)]
mod run_on_large_stack_tests {
    use super::run_on_large_stack;

    #[test]
    fn propagates_the_closure_exit_code() {
        assert_eq!(run_on_large_stack("test-exit", || 7), 7);
        assert_eq!(run_on_large_stack("test-exit", || 0), 0);
    }

    #[test]
    fn converts_a_panicking_closure_to_exit_one() {
        // A serve/api/watch entry that panics must never look like a clean
        // (exit 0) shutdown to a supervisor; the join boundary must catch the
        // unwind and report non-zero. (nextest's process-per-test isolation
        // contains the panic output.)
        assert_eq!(run_on_large_stack("test-panic", || panic!("boom")), 1);
    }

    #[test]
    fn runs_a_closure_needing_a_multi_mib_stack_frame() {
        // Runs a closure with a 4 MiB stack frame through the helper. This is a
        // weak sizing check, not a proof: the test env pins RUST_MIN_STACK=8 MiB
        // (root .cargo/config.toml), so a plain spawn would survive the frame
        // too — it would only overflow on the ~1 MiB Windows main-thread default
        // a ZEB-519 repo-root build links, which we can't reproduce in-process.
        // It mainly guards that the helper runs the closure and returns its
        // value; the real overflow backstop is the serve-spawn e2e path.
        let mib = run_on_large_stack("test-stack", || {
            let big = [0u8; 4 * 1024 * 1024];
            std::hint::black_box(&big);
            (big.len() / (1024 * 1024)) as i32
        });
        assert_eq!(mib, 4);
    }
}

/// ZEB-445: headless serve mode. Returns the process exit code.
///
/// Lifecycle (spec §Lifecycle, lock, and shutdown): tracing (stderr console,
/// ZEB-430 stdout purity) → tokio runtime → data dir → profile lock → node
/// auto-start → API server → wait for ctrl-c/SIGTERM or `/v1/shutdown` →
/// stop node → best-effort removal of the discovery files.
/// ZEB-882: pick the display name a headless `serve` node publishes on its owner
/// card. Explicit `--display-name` wins; otherwise fall back to the active
/// profile name; a bare anonymous serve (no flag, default profile) publishes no
/// card — it stays nameless rather than announcing a placeholder. Blank/
/// whitespace-only values are treated as absent, and a surrounding-whitespace
/// value is TRIMMED so the published name matches the blank-detection rule (a
/// `"  Ada  "` flag publishes `"Ada"`, not the padded string). Pure so the
/// policy is unit-testable without spawning serve.
fn resolve_serve_card_name(flag: Option<String>, profile: Option<String>) -> Option<String> {
    let trimmed_non_blank = |s: String| {
        let t = s.trim();
        if t.is_empty() {
            None
        } else {
            Some(t.to_string())
        }
    };
    flag.and_then(trimmed_non_blank)
        .or_else(|| profile.and_then(trimmed_non_blank))
}

#[cfg(test)]
mod serve_card_name_tests {
    use super::resolve_serve_card_name;

    #[test]
    fn flag_wins_over_profile() {
        assert_eq!(
            resolve_serve_card_name(Some("Koya".into()), Some("prof".into())),
            Some("Koya".into())
        );
    }

    #[test]
    fn falls_back_to_profile_when_no_flag() {
        assert_eq!(
            resolve_serve_card_name(None, Some("prof".into())),
            Some("prof".into())
        );
    }

    #[test]
    fn none_when_neither() {
        assert_eq!(resolve_serve_card_name(None, None), None);
    }

    #[test]
    fn blank_flag_falls_through_to_profile() {
        assert_eq!(
            resolve_serve_card_name(Some("   ".into()), Some("prof".into())),
            Some("prof".into())
        );
    }

    #[test]
    fn blank_both_is_none() {
        assert_eq!(
            resolve_serve_card_name(Some(String::new()), Some("  ".into())),
            None
        );
    }

    /// CR#8: the returned name is TRIMMED, so a surrounding-whitespace flag/profile
    /// publishes the clean name rather than the padded one.
    #[test]
    fn surrounding_whitespace_is_trimmed() {
        assert_eq!(
            resolve_serve_card_name(Some("  Ada  ".into()), None),
            Some("Ada".into())
        );
        assert_eq!(
            resolve_serve_card_name(None, Some("\tKoya\n".into())),
            Some("Koya".into())
        );
    }
}

pub fn serve_cli(api_port: Option<u16>, display_name: Option<String>) -> i32 {
    crate::app_tracing::init_serve_tracing();

    // ZEB-446: fail fast on a named profile with no vault passphrase —
    // named profiles are file-vault-only (OS keychain refused), so the
    // node would otherwise boot into ZEB-450-style silent degradation at
    // the first vault access.
    if crate::profile::active_profile().is_some() && !crate::identity::passphrase_env_configured() {
        eprintln!(
            "serve: named profile requires HARMONY_PASSPHRASE or a readable \
             HARMONY_PASSPHRASE_FILE (named profiles use the encrypted-file vault, \
             not the OS keychain)"
        );
        // Exit code 1 = serve's uniform startup-failure code (lock taken,
        // data dir, node start). The GUI path exits 2 for the same
        // condition — 2 is main.rs's pre-launch config-error code (invalid
        // profile name, refused argv fall-through).
        return 1;
    }

    let rt = match tokio::runtime::Builder::new_multi_thread()
        // ZEB-519: size Zenoh/tokio worker threads independently of
        // RUST_MIN_STACK (which only reaches Cargo-spawned launches), matching
        // the `harmony-runtime` GUI runtime. The block_on *driver* thread is
        // sized separately by `run_on_large_stack`.
        .thread_stack_size(8 * 1024 * 1024)
        .enable_all()
        .build()
    {
        Ok(rt) => rt,
        Err(e) => {
            eprintln!("serve: cannot build tokio runtime: {e}");
            return 1;
        }
    };

    rt.block_on(async move {
        let data_dir = match crate::resolve_app_data_dir() {
            Ok(d) => d,
            Err(e) => {
                eprintln!("serve: {e}");
                return 1;
            }
        };

        // One node per profile: the OS advisory lock turns a second serve
        // (or a GUI-with-API) on the same profile into a loud refusal
        // instead of silent state-file races. Held until process exit.
        let _lock = match crate::api::lock::acquire(&data_dir.join("api")) {
            Ok(l) => l,
            Err(e) => {
                eprintln!("serve: {e}");
                return 1;
            }
        };

        let state = std::sync::Arc::new(Mutex::new(NodeState::default()));
        let events = crate::api::events::ApiEventSink::new();
        let sink: std::sync::Arc<dyn crate::node_event_sink::NodeEventSink> =
            std::sync::Arc::new(events.clone());

        // serve auto-starts the node — a serve process with a stopped node
        // is a transient state (after stop_node RPC), not the default.
        if let Err(e) = start_node_inner(
            None,
            sink.clone(),
            None,
            &state,
            Some(std::sync::Arc::clone(&state)),
        )
        .await
        {
            eprintln!("serve: node start failed: {e}");
            return 1;
        }

        // ZEB-613: headless presence parity — engage beacon + roster for
        // every joined community so presence-kick recovery works on serve
        // nodes without a manual `api subscribe_community_presence`.
        let _ = auto_subscribe_presence_all_communities(state.as_ref()).await;

        // ZEB-882: headless card parity — a serve node otherwise never publishes
        // an owner card (no frontend to call republish_owner_card), so peers only
        // ever see its hex address. Publish one now using --display-name, falling
        // back to the active profile name. A bare anonymous serve stays nameless.
        if let Some(name) = resolve_serve_card_name(
            display_name,
            crate::profile::active_profile().map(str::to_string),
        ) {
            match republish_owner_card_impl(state.as_ref(), name.clone(), String::new(), None, None)
                .await
            {
                Ok(()) => tracing::info!(display_name = %name, "serve: published owner card"),
                Err(e) => tracing::warn!(display_name = %name, error = %e, "serve: owner card publish failed (peers will see a hex address)"),
            }
        } else {
            tracing::info!(
                "serve: no --display-name and no named profile; not publishing an owner card (nameless to peers)"
            );
        }

        let port = api_port
            .or_else(|| {
                std::env::var("HARMONY_API_PORT")
                    .ok()
                    .and_then(|v| v.parse().ok())
            })
            .unwrap_or(7420);

        let (shutdown_tx, shutdown_rx) = tokio::sync::mpsc::channel::<()>(1);
        let (handle, server_task) = match crate::api::start_server(
            &data_dir,
            port,
            state.clone(),
            sink,
            events,
            shutdown_tx.clone(),
            shutdown_rx,
        )
        .await
        {
            Ok(x) => x,
            Err(e) => {
                eprintln!("serve: {e}");
                stop_inner(&state, None);
                return 1;
            }
        };

        tracing::info!(
            port = handle.bound_port,
            "harmony serve listening on 127.0.0.1"
        );

        // Two exit paths converge here:
        //  - OS signal (ctrl-c / SIGTERM): nudge the shutdown channel, then
        //    give the server's graceful drain a bounded window.
        //  - `/v1/shutdown` RPC: the handler already sent on the channel;
        //    the server task ends and the select's second arm fires (the
        //    JoinHandle is already complete — do NOT poll it again).
        // Either way the join OUTCOME decides the exit code: a server task
        // that ended with a serve error or panic must not exit 0, or
        // supervisors would mistake a crash for a clean shutdown.
        fn eval_server_join(join: Result<Result<(), String>, tokio::task::JoinError>) -> i32 {
            match join {
                Ok(Ok(())) => 0,
                Ok(Err(e)) => {
                    eprintln!("serve: api server failed: {e}");
                    1
                }
                Err(e) => {
                    eprintln!("serve: api server task aborted: {e}");
                    1
                }
            }
        }
        let mut server_task = server_task;
        let exit_code = tokio::select! {
            _ = wait_for_exit_signal() => {
                let _ = shutdown_tx.send(()).await;
                match tokio::time::timeout(
                    std::time::Duration::from_secs(10),
                    &mut server_task,
                )
                .await
                {
                    Ok(join) => eval_server_join(join),
                    Err(_) => {
                        tracing::warn!(
                            "serve: server did not drain within 10s; continuing shutdown"
                        );
                        1
                    }
                }
            }
            join = &mut server_task => eval_server_join(join),
        };

        stop_inner(&state, None);

        // Best-effort discovery-file cleanup: a stale port/token file is
        // only a confusing client error, never a correctness issue (they
        // are rewritten on every server start).
        let _ = std::fs::remove_file(handle.api_dir.join("port"));
        let _ = std::fs::remove_file(handle.api_dir.join("token"));
        exit_code
    })
}

/// ZEB-452: `harmony-app api` CLI entry (thin client for the localhost API).
pub use crate::api::cli::api_cli;
pub use crate::api::watch::{api_watch, WatchConfig};

/// ZEB-445: resolve on ctrl-c (all platforms) or SIGTERM (unix — what
/// systemd / `kill` send). Never resolves spuriously: if no handler can be
/// installed, falls back to ctrl-c alone.
async fn wait_for_exit_signal() {
    #[cfg(unix)]
    {
        let mut sigterm = match tokio::signal::unix::signal(
            tokio::signal::unix::SignalKind::terminate(),
        ) {
            Ok(s) => s,
            Err(e) => {
                tracing::warn!(error = %e, "serve: cannot install SIGTERM handler; ctrl-c only");
                let _ = tokio::signal::ctrl_c().await;
                return;
            }
        };
        tokio::select! {
            _ = tokio::signal::ctrl_c() => {}
            _ = sigterm.recv() => {}
        }
    }
    #[cfg(not(unix))]
    {
        let _ = tokio::signal::ctrl_c().await;
    }
}

// ── ZEB-217 community IPC types ──────────────────────────────────────────

/// Frontend-facing member status. Mirrors `MemberStatus` from
/// `community_membership` but serializes with human-readable strings
/// ("joined" / "left" / "invited" / "banned") instead of the CBOR wire
/// codes ("j" / "l" / "i" / "b") — the CBOR renames exist for canonical
/// CBOR compactness on the wire, but the Tauri IPC boundary should
/// surface a string the frontend can read directly without a lookup
/// table.
#[derive(Debug, Clone, Copy, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum MemberStatusDto {
    Joined,
    Left,
    Invited,
    Banned,
    /// ZEB-254: joiner has minted a PendingJoin awaiting admin counter-sign.
    PendingJoin,
}

impl From<crate::community_membership::MemberStatus> for MemberStatusDto {
    fn from(s: crate::community_membership::MemberStatus) -> Self {
        use crate::community_membership::MemberStatus;
        match s {
            MemberStatus::Joined => Self::Joined,
            MemberStatus::Left => Self::Left,
            MemberStatus::Invited => Self::Invited,
            MemberStatus::Banned => Self::Banned,
            // ZEB-254: wired in Task 4 (IPC).
            MemberStatus::PendingJoin => Self::PendingJoin,
        }
    }
}

/// Member-list row returned by `list_community_members` IPC. Mirrors
/// the spec's MemberInfo type. `addr` is hex of OwnerAddr (16 bytes →
/// 32 chars). `display_name` is None in Phase 3 — the existing profile
/// cache lookup is wired in Phase 5.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct MemberInfoDto {
    pub addr: String,
    pub display_name: Option<String>,
    pub status: MemberStatusDto,
    pub power: u8,
    pub joined_at: crate::owner_state_types::Hlc,
}

/// Event-kind discriminant for `ModerationEventDto`. Serializes as
/// `"kick" | "unban" | "set_power"` (snake_case) for the JS bridge.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ModerationEventKindDto {
    Kick,
    Unban,
    SetPower,
}

/// One moderation action returned by `list_recent_moderation_events`.
/// Covers Kick, Unban, and SetPower event kinds only; channel-config
/// and epoch events are filtered out by the IPC.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ModerationEventDto {
    /// Hex-encoded 16-byte EventId (32 chars).
    pub event_id: String,
    pub kind: ModerationEventKindDto,
    /// Hex-encoded actor OwnerAddr (32 chars).
    pub actor_addr: String,
    /// Hex-encoded target OwnerAddr (32 chars).
    pub target_addr: String,
    /// Free-text reason signed into the CRDT event; None for SetPower.
    /// Serialized as `null` (not omitted) so the JS side observes
    /// `reason: null` not `reason: undefined` — matches the TS contract
    /// `string | null` rather than introducing `undefined` semantics.
    pub reason: Option<String>,
    /// New power level; None for Kick and Unban. Serialized as `null`
    /// (not omitted) — same rationale as `reason`.
    pub new_power: Option<u8>,
    /// HLC at which the event was signed and inserted.
    pub hlc: crate::owner_state_types::Hlc,
}

/// ZEB-250: discriminated result of an admin moderation IPC. The
/// handler auto-routes based on the target community's admin_quorum:
/// - `Completed` if admin_quorum == 1 OR action is not admin-affecting.
/// - `Pending` if admin_quorum > 1 AND action is admin-affecting — an
///   AdminProposal was minted instead and is awaiting countersignatures.
#[derive(Debug, Clone, serde::Serialize)]
#[serde(tag = "kind")]
pub enum AdminActionResult {
    Completed,
    Pending {
        proposal_event_id: String,
        signers_so_far: u8,
        quorum_required: u8,
    },
}

/// ZEB-250 §6.3: return type for `countersign_admin_proposal` IPC.
/// Reports the signer count after the (possibly no-op idempotent)
/// operation, the community's current quorum requirement, and whether
/// quorum has been reached.
#[derive(Debug, Clone, serde::Serialize)]
pub struct CountersignResult {
    pub signers_after: u8,
    pub quorum_required: u8,
    pub reached_quorum: bool,
}

/// Project a materialized membership into the IPC DTO list, sorted by
/// power level descending then joined_at ascending. Stable for two
/// addrs at the same power+joined_at — falls through to OwnerAddr-bytes
/// comparison so the order is deterministic across calls.
pub fn member_info_for(
    m: &crate::community_membership::MaterializedMembership,
) -> Vec<MemberInfoDto> {
    let mut rows: Vec<MemberInfoDto> = m
        .members
        .iter()
        .map(|(addr, state)| MemberInfoDto {
            addr: hex::encode(addr.0),
            display_name: None,
            status: state.status.into(),
            power: m.power_levels.get(addr).copied().unwrap_or(0),
            joined_at: state.joined_at.clone(),
        })
        .collect();
    rows.sort_by(|a, b| {
        b.power
            .cmp(&a.power)
            .then_with(|| a.joined_at.wall_ms.cmp(&b.joined_at.wall_ms))
            .then_with(|| a.joined_at.logical.cmp(&b.joined_at.logical))
            .then_with(|| a.addr.cmp(&b.addr))
    });
    rows
}

/// ZEB-393 Bug B: a persisted Community space shaped for the nav sidebar.
/// `space_id` is the 32-char lowercase hex of the 16-byte SpaceId (same
/// format the runtime `nav-updated` emit uses). Mirrors the frontend
/// `CommunityNavDto` in `community-service.ts`.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct CommunityNavDto {
    pub space_id: String,
    pub name: String,
    pub is_invite_only: bool,
    pub pending: bool,
}

/// ZEB-393 Bug B: owner-state Community spaces shaped for boot rehydration
/// of the nav sidebar. Filters to live (non-left) Community spaces —
/// mirrors the boot engine-spawn sweep's predicate (`start_node`) so the UI
/// and the engine sweep agree on "which communities am I in." The frontend
/// has no other way to learn this: `list_community_members` /
/// `list_community_forks` both require a `communityId` you must already have.
pub fn communities_for_nav(state: &crate::owner_state_crdt::OwnerState) -> Vec<CommunityNavDto> {
    state
        .spaces
        .values()
        .filter(|s| s.kind == crate::owner_state_types::SpaceKind::Community && s.left_at.is_none())
        .map(|s| CommunityNavDto {
            space_id: hex::encode(s.id.0),
            name: s.name.clone(),
            is_invite_only: s.is_invite_only.unwrap_or(false),
            pending: s.pending_join_at.is_some(),
        })
        .collect()
}

/// ZEB-393 Bug B: enumerate the viewer's live (non-left) communities for
/// boot rehydration of the nav sidebar. The frontend has no other way to
/// learn "which communities am I in" — the nav tree is otherwise push-only
/// (filled by runtime `nav-updated` events) and boots empty on every
/// restart. Read-only over the in-memory owner-state CRDT (populated at
/// `start_node` by `load_crdt`). App.svelte calls this after
/// `navService.connectAdapter` and seeds via `addOrUpdateNavSpace`.
#[tauri::command]
async fn list_owner_communities(
    state_lock: tauri::State<'_, std::sync::Mutex<NodeState>>,
) -> Result<Vec<CommunityNavDto>, String> {
    list_owner_communities_impl(state_lock.inner()).await
}

/// ZEB-445: shared IPC/RPC seam.
pub(crate) async fn list_owner_communities_impl(
    state: &std::sync::Mutex<NodeState>,
) -> Result<Vec<CommunityNavDto>, String> {
    let crdt_state = {
        let g = state
            .lock()
            .map_err(|e| format!("NodeState poisoned: {e}"))?;
        g.crdt_state
            .clone()
            .ok_or_else(|| g.owner_not_loaded_msg())?
    };
    let state = crdt_state.lock().await;
    Ok(communities_for_nav(&state))
}

/// ZEB-666: a persisted DM / group-DM space shaped for the nav sidebar.
/// `space_id` is the 32-char lowercase hex of the 16-byte SpaceId; `kind`
/// uses the `nav-updated` vocabulary ("dm" | "group-dm") so the frontend can
/// feed rows straight into `addOrUpdateNavSpace`.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct DmNavDto {
    pub space_id: String,
    pub kind: String,
    /// `custom_name` (user rename) wins over the space's original name.
    pub name: String,
    /// Hex-encoded member OwnerAddrs (self included — the frontend derives
    /// the 1:1 peer as "whichever member isn't me", exactly as it does for
    /// the runtime `nav-updated` emit's `members`).
    pub members: Vec<String>,
}

/// ZEB-666: owner-state DM / group-DM spaces shaped for boot rehydration of
/// the nav sidebar (the ZEB-393 `communities_for_nav` pattern). Filters to
/// live (non-left) spaces. The frontend has no other way to learn "which DM
/// threads do I have" — DM nav rows are otherwise push-only (runtime
/// `nav-updated` / `handleDmCreate`) and vanish on every restart, which
/// would strand the persisted per-thread read cursors.
pub fn dm_spaces_for_nav(state: &crate::owner_state_crdt::OwnerState) -> Vec<DmNavDto> {
    use crate::owner_state_types::SpaceKind;
    state
        .spaces
        .values()
        .filter(|s| matches!(s.kind, SpaceKind::Dm | SpaceKind::GroupDm) && s.left_at.is_none())
        .map(|s| DmNavDto {
            space_id: hex::encode(s.id.0),
            kind: match s.kind {
                SpaceKind::GroupDm => "group-dm".to_string(),
                SpaceKind::Dm => "dm".to_string(),
                // The filter above restricts to Dm | GroupDm; keep the arms
                // explicit so a loosened filter can't silently misclassify.
                _ => unreachable!("dm_spaces_for_nav filters to Dm | GroupDm"),
            },
            name: s.custom_name.clone().unwrap_or_else(|| s.name.clone()),
            members: s.members.iter().map(|m| hex::encode(m.0)).collect(),
        })
        .collect()
}

/// ZEB-666: enumerate the viewer's live DM / group-DM spaces for boot
/// rehydration of the nav sidebar. Read-only over the in-memory owner-state
/// CRDT (populated at `start_node` by `load_crdt`). App.svelte calls this
/// right after community rehydration (after `navService.connectAdapter`)
/// and seeds via `addOrUpdateNavSpace`.
#[tauri::command]
async fn list_owner_dm_spaces(
    state_lock: tauri::State<'_, std::sync::Mutex<NodeState>>,
) -> Result<Vec<DmNavDto>, String> {
    list_owner_dm_spaces_impl(state_lock.inner()).await
}

/// ZEB-445: shared IPC/RPC seam.
pub(crate) async fn list_owner_dm_spaces_impl(
    state: &std::sync::Mutex<NodeState>,
) -> Result<Vec<DmNavDto>, String> {
    let crdt_state = {
        let g = state
            .lock()
            .map_err(|e| format!("NodeState poisoned: {e}"))?;
        g.crdt_state
            .clone()
            .ok_or_else(|| g.owner_not_loaded_msg())?
    };
    let state = crdt_state.lock().await;
    Ok(dm_spaces_for_nav(&state))
}

/// ZEB-435 (scope #4): a left-but-not-deleted community Space shaped for the
/// left-communities management surface. Mirrors `LeftCommunityNavDto` in
/// `community-service.ts` (`#[serde(rename_all = "camelCase")]`). `left_at_ms`
/// is the leave HLC's wall clock, for "Left <date>" display.
#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub struct LeftCommunityNavDto {
    pub space_id: String,
    pub name: String,
    pub left_at_ms: u64,
}

/// ZEB-435 (scope #4): enumerate left (but not deleted-forever) Community
/// spaces for the management surface — the exact complement of
/// `communities_for_nav`'s live filter. Tombstoned spaces are already removed
/// from `spaces` by `tombstone_space`, so a deleted-forever community never
/// reappears here. Most recently left first; space-id tiebreak keeps the
/// order deterministic.
pub fn left_communities_for_nav(
    state: &crate::owner_state_crdt::OwnerState,
) -> Vec<LeftCommunityNavDto> {
    let mut rows: Vec<LeftCommunityNavDto> = state
        .spaces
        .values()
        .filter_map(|s| {
            if s.kind != crate::owner_state_types::SpaceKind::Community {
                return None;
            }
            let left_at = s.left_at.as_ref()?;
            Some(LeftCommunityNavDto {
                space_id: hex::encode(s.id.0),
                name: s.name.clone(),
                left_at_ms: left_at.wall_ms,
            })
        })
        .collect();
    rows.sort_by(|a, b| {
        b.left_at_ms
            .cmp(&a.left_at_ms)
            .then_with(|| a.space_id.cmp(&b.space_id))
    });
    rows
}

/// ZEB-435 (scope #4): list left communities for the management surface — the
/// only way to reach a left community once it's hidden from nav (ZEB-427 a′).
/// Read-only over the in-memory owner-state CRDT.
#[tauri::command]
async fn list_left_communities(
    state_lock: tauri::State<'_, std::sync::Mutex<NodeState>>,
) -> Result<Vec<LeftCommunityNavDto>, String> {
    list_left_communities_impl(state_lock.inner()).await
}

/// ZEB-445: shared IPC/RPC seam.
pub(crate) async fn list_left_communities_impl(
    state: &std::sync::Mutex<NodeState>,
) -> Result<Vec<LeftCommunityNavDto>, String> {
    let crdt_state = {
        let g = state
            .lock()
            .map_err(|e| format!("NodeState poisoned: {e}"))?;
        g.crdt_state
            .clone()
            .ok_or_else(|| g.owner_not_loaded_msg())?
    };
    let state = crdt_state.lock().await;
    Ok(left_communities_for_nav(&state))
}

#[cfg(test)]
mod zeb435_left_communities_for_nav_tests {
    use super::*;
    use crate::owner_state_crdt::OwnerState;
    use crate::owner_state_types::{Hlc, Space, SpaceId, SpaceKind};

    fn hlc_at(wall_ms: u64) -> Hlc {
        Hlc {
            wall_ms,
            logical: 0,
            device_id: "t".into(),
        }
    }

    fn space(id: u8, kind: SpaceKind, left_wall_ms: Option<u64>) -> Space {
        Space {
            id: SpaceId([id; 16]),
            kind,
            parent: None,
            community_id: None,
            name: format!("community-{id}"),
            transport: None,
            members: vec![],
            custom_name: None,
            notification_pref: None,
            left_at: left_wall_ms.map(hlc_at),
            created_at: hlc_at(1),
            updated_at: hlc_at(1),
            content_key: None,
            prior_content_keys: vec![],
            current_epoch: None,
            current_epoch_key: None,
            old_epoch_keys: std::collections::BTreeMap::new(),
            admin_addr: None,
            is_invite_only: Some(false),
            shared_in_profile: false,
            read_receipt_pref: None,
            pending_join_at: None,
        }
    }

    fn state_with(spaces: Vec<Space>) -> OwnerState {
        let mut st = OwnerState::default();
        for s in spaces {
            st.spaces.insert(s.id, s);
        }
        st
    }

    #[test]
    fn lists_only_left_communities_with_wall_ms() {
        let st = state_with(vec![
            space(1, SpaceKind::Community, None),
            space(2, SpaceKind::Community, Some(500)),
            space(3, SpaceKind::Dm, Some(600)),
        ]);
        let rows = left_communities_for_nav(&st);
        assert_eq!(rows.len(), 1, "only the LEFT community qualifies");
        assert_eq!(rows[0].space_id, hex::encode([2u8; 16]));
        assert_eq!(rows[0].name, "community-2");
        assert_eq!(rows[0].left_at_ms, 500);
        // Exact complement of the live nav list: between them every
        // non-tombstoned community appears exactly once.
        assert_eq!(communities_for_nav(&st).len(), 1);
    }

    #[test]
    fn sorts_most_recent_first_with_space_id_tiebreak() {
        let st = state_with(vec![
            space(1, SpaceKind::Community, Some(100)),
            space(2, SpaceKind::Community, Some(300)),
            space(3, SpaceKind::Community, Some(100)),
        ]);
        let got: Vec<String> = left_communities_for_nav(&st)
            .into_iter()
            .map(|r| r.space_id)
            .collect();
        assert_eq!(
            got,
            vec![
                hex::encode([2u8; 16]),
                hex::encode([1u8; 16]),
                hex::encode([3u8; 16]),
            ],
            "most recently left first, space-id asc on ties"
        );
    }

    #[test]
    fn tombstoned_spaces_never_appear() {
        let mut st = state_with(vec![space(4, SpaceKind::Community, Some(700))]);
        assert_eq!(left_communities_for_nav(&st).len(), 1);
        st.tombstone_space(SpaceId([4; 16]));
        assert!(
            left_communities_for_nav(&st).is_empty(),
            "delete-forever (tombstone) removes the row from the surface"
        );
    }
}

#[cfg(test)]
mod zeb393_communities_for_nav_tests {
    use super::*;
    use crate::owner_state_crdt::OwnerState;
    use crate::owner_state_types::{EpochKey, Hlc, OwnerAddr, Space, SpaceId, SpaceKind};

    fn hlc() -> Hlc {
        Hlc {
            wall_ms: 100,
            logical: 0,
            device_id: "test".into(),
        }
    }

    fn community_space(id: u8, name: &str, invite_only: bool, pending: bool, left: bool) -> Space {
        Space {
            id: SpaceId([id; 16]),
            kind: SpaceKind::Community,
            parent: None,
            community_id: None,
            name: name.into(),
            transport: None,
            members: vec![],
            custom_name: None,
            notification_pref: None,
            left_at: if left { Some(hlc()) } else { None },
            created_at: hlc(),
            updated_at: hlc(),
            content_key: None,
            prior_content_keys: vec![],
            current_epoch: Some(0),
            current_epoch_key: Some(EpochKey::new([7u8; 32])),
            old_epoch_keys: std::collections::BTreeMap::new(),
            admin_addr: Some(OwnerAddr([9u8; 16])),
            is_invite_only: Some(invite_only),
            shared_in_profile: false,
            read_receipt_pref: None,
            pending_join_at: if pending { Some(hlc()) } else { None },
        }
    }

    fn folder_space(id: u8, name: &str) -> Space {
        let mut s = community_space(id, name, false, false, false);
        s.kind = SpaceKind::Folder;
        s.current_epoch = None;
        s.current_epoch_key = None;
        s.admin_addr = None;
        s.is_invite_only = None;
        s
    }

    #[test]
    fn returns_only_live_communities_with_correct_fields() {
        let mut st = OwnerState::default();
        for s in [
            community_space(1, "Open Town", false, false, false),
            community_space(2, "Secret Club", true, true, false), // pending invite-only
            community_space(3, "Left Behind", false, false, true), // left → excluded
            folder_space(4, "Root"),                              // non-community → excluded
        ] {
            st.spaces.insert(s.id, s);
        }

        let mut got = communities_for_nav(&st);
        got.sort_by(|a, b| a.space_id.cmp(&b.space_id));

        assert_eq!(got.len(), 2, "only the two live communities");
        assert_eq!(got[0].space_id, hex::encode([1u8; 16]));
        assert_eq!(got[0].name, "Open Town");
        assert!(!got[0].is_invite_only);
        assert!(!got[0].pending);
        assert_eq!(got[1].name, "Secret Club");
        assert!(got[1].is_invite_only);
        assert!(
            got[1].pending,
            "invite-only pending join stays greyed at boot"
        );
    }

    #[test]
    fn empty_state_yields_empty() {
        assert!(communities_for_nav(&OwnerState::default()).is_empty());
    }
}

