#[cfg(test)]
mod community_member_dto_tests {
    use super::{member_info_for, MemberStatusDto};
    use crate::community_membership::{MaterializedMembership, MemberState, MemberStatus};
    use crate::owner_state_types::{Hlc, OwnerAddr};
    use std::collections::BTreeMap;

    fn hlc(wall: u64, dev: &str) -> Hlc {
        Hlc {
            wall_ms: wall,
            logical: 0,
            device_id: dev.to_string(),
        }
    }

    #[test]
    fn member_info_sorts_by_power_desc_then_joined_at_asc() {
        let admin = OwnerAddr([1; 16]);
        let mod_user = OwnerAddr([2; 16]);
        let early = OwnerAddr([3; 16]);
        let late = OwnerAddr([4; 16]);

        let mut members = BTreeMap::new();
        members.insert(
            admin,
            MemberState {
                status: MemberStatus::Joined,
                joined_at: hlc(100, "a"),
                left_at: None,
                enrolled_device_keys: std::collections::BTreeSet::new(),
                revoked_device_keys: std::collections::BTreeSet::new(),
            },
        );
        members.insert(
            mod_user,
            MemberState {
                status: MemberStatus::Joined,
                joined_at: hlc(200, "b"),
                left_at: None,
                enrolled_device_keys: std::collections::BTreeSet::new(),
                revoked_device_keys: std::collections::BTreeSet::new(),
            },
        );
        members.insert(
            early,
            MemberState {
                status: MemberStatus::Joined,
                joined_at: hlc(150, "c"),
                left_at: None,
                enrolled_device_keys: std::collections::BTreeSet::new(),
                revoked_device_keys: std::collections::BTreeSet::new(),
            },
        );
        members.insert(
            late,
            MemberState {
                status: MemberStatus::Joined,
                joined_at: hlc(300, "d"),
                left_at: None,
                enrolled_device_keys: std::collections::BTreeSet::new(),
                revoked_device_keys: std::collections::BTreeSet::new(),
            },
        );

        let mut power_levels = BTreeMap::new();
        power_levels.insert(admin, 100);
        power_levels.insert(mod_user, 50);

        let materialized = MaterializedMembership {
            members,
            power_levels,
            channels: BTreeMap::new(),
            current_epoch: None,
            pending_rotation_for: std::collections::BTreeSet::new(),
            pending_catchup_for: std::collections::BTreeSet::new(),
            admin_quorum: 1,
            power_thresholds: crate::community_membership::POWER_THRESHOLDS,
            recovery_designates: None,
            recovery_proposals: Vec::new(),
        };
        let dto = member_info_for(&materialized);

        assert_eq!(dto.len(), 4);
        assert_eq!(dto[0].addr, hex::encode(admin.0));
        assert_eq!(dto[0].power, 100);
        assert_eq!(dto[1].addr, hex::encode(mod_user.0));
        assert_eq!(dto[1].power, 50);
        assert_eq!(dto[2].addr, hex::encode(early.0));
        assert_eq!(dto[2].power, 0);
        assert_eq!(dto[3].addr, hex::encode(late.0));
        assert_eq!(dto[3].power, 0);
    }

    #[test]
    fn member_info_includes_left_and_banned_members() {
        let a = OwnerAddr([1; 16]);
        let b = OwnerAddr([2; 16]);
        let mut members = BTreeMap::new();
        members.insert(
            a,
            MemberState {
                status: MemberStatus::Left,
                joined_at: hlc(100, "x"),
                left_at: Some(hlc(200, "x")),
                enrolled_device_keys: std::collections::BTreeSet::new(),
                revoked_device_keys: std::collections::BTreeSet::new(),
            },
        );
        members.insert(
            b,
            MemberState {
                status: MemberStatus::Banned,
                joined_at: hlc(50, "y"),
                left_at: Some(hlc(150, "y")),
                enrolled_device_keys: std::collections::BTreeSet::new(),
                revoked_device_keys: std::collections::BTreeSet::new(),
            },
        );
        let materialized = MaterializedMembership {
            members,
            power_levels: BTreeMap::new(),
            channels: BTreeMap::new(),
            current_epoch: None,
            pending_rotation_for: std::collections::BTreeSet::new(),
            pending_catchup_for: std::collections::BTreeSet::new(),
            admin_quorum: 1,
            power_thresholds: crate::community_membership::POWER_THRESHOLDS,
            recovery_designates: None,
            recovery_proposals: Vec::new(),
        };
        let dto = member_info_for(&materialized);
        assert_eq!(dto.len(), 2);
        let statuses: Vec<_> = dto.iter().map(|d| d.status).collect();
        assert!(statuses.contains(&MemberStatusDto::Left));
        assert!(statuses.contains(&MemberStatusDto::Banned));
    }
}

// ── ZEB-290 voting IPCs ──────────────────────────────────────────────────
//
// Phase 1 Task 11: four read+write IPCs that drive Tier 1 (Approval)
// voting against per-community in-memory `VotingLog`s on `NodeState`.
//
// IMPORTANT scope notes (deferred to later tasks):
// - Zenoh publish (so peers see the event): Task 12.
// - Disk persistence: Task 13.
// - Auto-close on window expiry: Task 13.
// - Multi-engine integration tests: Task 15.
//
// Pre-flight ordering follows the metadata-before-irreversible-write
// rule (see `feedback_metadata_before_irreversible_write`): we
// validate the config, build the snapshot, and run eligibility
// BEFORE signing the event. A doomed event never gets minted.

/// Build a `MembershipSnapshot` for `community_id` from the engine's
/// materialized state at the current HLC. The IPC supplies this to
/// `apply_with_snapshot` so future ballot validation can run eligibility
/// against the frozen snapshot (spec §7) without re-querying CRDT state.
///
/// Phase 1 simplification: `vouching_depth` is set to 0 for every
/// member. The Sybil-resistance gate (`min_vouching_depth`) is not yet
/// enforceable until the vouching log lands (post-Phase 1); for now
/// the IPC rejects any `min_vouching_depth > 0` request at the
/// boundary so we never silently admit ineligible voters. Removing
/// this restriction is tracked under the same epic as the vouching
/// log ticket.
async fn voting_build_snapshot_for_community(
    crdt_state: std::sync::Arc<tokio::sync::Mutex<crate::owner_state_crdt::OwnerState>>,
    community_registry: std::sync::Arc<crate::community_state_sync::CommunitySyncRegistry>,
    space_id: crate::owner_state_types::SpaceId,
) -> Result<crate::community_voting_core::MembershipSnapshot, String> {
    let (admin_addr, engine_state) =
        voting_resolve_membership_source(&crdt_state, &community_registry, space_id).await?;

    let materialized = {
        let g = engine_state.lock().await;
        g.materialize_now(admin_addr)
    };
    Ok(voting_membership_snapshot_from_materialized(&materialized))
}

/// ZEB-315: at-event-HLC variant of `voting_build_snapshot_for_community`.
/// Re-materializes the community-membership CRDT from the event prefix
/// strictly before `at` (via `prior_state_at_hlc`, the same projection the
/// channel-log verify chain uses through `CommunityStateAtHlcAdapter`), so
/// inbound voting events are verified against the membership that held at
/// the event's own HLC — a member removed AFTER signing no longer has their
/// in-flight events rejected during membership churn (spec §10 rolling
/// eligibility).
///
/// `at` is caller-supplied and untrusted (it comes from the event being
/// verified); see the SECURITY POSTURE note on
/// `NodeStateMembershipResolver` for why that is accepted here and where
/// post-removal injection is actually contained (ZEB-717 transport
/// encryption).
async fn voting_build_snapshot_for_community_at_hlc(
    crdt_state: std::sync::Arc<tokio::sync::Mutex<crate::owner_state_crdt::OwnerState>>,
    community_registry: std::sync::Arc<crate::community_state_sync::CommunitySyncRegistry>,
    space_id: crate::owner_state_types::SpaceId,
    at: &crate::owner_state_types::Hlc,
) -> Result<crate::community_voting_core::MembershipSnapshot, String> {
    let (admin_addr, engine_state) =
        voting_resolve_membership_source(&crdt_state, &community_registry, space_id).await?;

    // CommunityStateAtHlcAdapter lock posture: snapshot the event log under
    // the lock, drop the guard, then run the pure `prior_state_at_hlc`
    // replay — no need to block the community engine's writer for the
    // O(events) walk.
    let events: Vec<crate::community_membership::SignedMembershipEvent> = {
        let g = engine_state.lock().await;
        g.events().cloned().collect()
    };
    let materialized = crate::community_membership::prior_state_at_hlc(&events, at, admin_addr);
    Ok(voting_membership_snapshot_from_materialized(&materialized))
}

/// Shared by the at-HEAD and at-HLC snapshot builders: resolve the
/// community's `admin_addr` from owner-state and the membership CRDT handle
/// from the sync registry.
async fn voting_resolve_membership_source(
    crdt_state: &std::sync::Arc<tokio::sync::Mutex<crate::owner_state_crdt::OwnerState>>,
    community_registry: &std::sync::Arc<crate::community_state_sync::CommunitySyncRegistry>,
    space_id: crate::owner_state_types::SpaceId,
) -> Result<
    (
        crate::owner_state_types::OwnerAddr,
        std::sync::Arc<tokio::sync::Mutex<crate::community_state_crdt::CommunityState>>,
    ),
    String,
> {
    let admin_addr = {
        let s = crdt_state.lock().await;
        let space = s.spaces.get(&space_id).cloned();
        drop(s);
        let space = space.ok_or_else(|| {
            format!(
                "no Space for community {} in owner-state",
                hex::encode(space_id.0)
            )
        })?;
        if space.kind != crate::owner_state_types::SpaceKind::Community {
            return Err(format!(
                "Space {} exists but is kind {:?}, not Community",
                hex::encode(space_id.0),
                space.kind
            ));
        }
        space
            .admin_addr
            .ok_or("community Space missing admin_addr (corrupt row?)")?
    };

    let engine_state = community_registry
        .state_for(&space_id)
        .await
        .ok_or_else(|| {
            format!(
                "no engine for community {} — not joined or not yet started",
                hex::encode(space_id.0)
            )
        })?;
    Ok((admin_addr, engine_state))
}

/// Project a `MaterializedMembership` into the voting layer's
/// `MembershipSnapshot`: Joined members only, with their power levels.
fn voting_membership_snapshot_from_materialized(
    materialized: &crate::community_membership::MaterializedMembership,
) -> crate::community_voting_core::MembershipSnapshot {
    let mut members = std::collections::HashMap::new();
    for (addr, state) in materialized.members.iter() {
        // Only Joined members are eligible voters in Phase 1. Invited /
        // PendingJoin / Left / Banned are excluded so even
        // `min_power: 0` polls don't admit them.
        if !matches!(
            state.status,
            crate::community_membership::MemberStatus::Joined
        ) {
            continue;
        }
        let power = *materialized.power_levels.get(addr).unwrap_or(&0);
        members.insert(
            *addr,
            crate::community_voting_core::MemberAttrs {
                power,
                // TODO(post-Phase-1): wire vouching-depth from the
                // vouching log once it lands. The IPC boundary already
                // rejects min_vouching_depth>0 today so 0 is safe.
                vouching_depth: 0,
            },
        );
    }
    crate::community_voting_core::MembershipSnapshot { members }
}

/// Pure helper used by both `voting_create_tier1_poll` and the unit
/// test: assemble a `Tier1PollConfig` from raw IPC args + validate it.
#[allow(clippy::too_many_arguments)]
fn voting_build_tier1_config(
    channel_id: crate::community_membership::ChannelId,
    options: Vec<String>,
    window_seconds: u32,
    min_power: u8,
    min_vouching_depth: Option<u8>,
    quorum: Option<u32>,
    threshold_percent: Option<u8>,
    multi_winner: Option<u8>,
) -> Result<crate::community_voting_approval::Tier1PollConfig, String> {
    // Phase 1 hard rule: reject min_vouching_depth>0 because the
    // snapshot helper hardcodes vouching_depth=0 — accepting >0 would
    // make every poll effectively unvotable and confuse the UI.
    if let Some(mv) = min_vouching_depth {
        if mv > 0 {
            return Err(
                "voting_create_tier1_poll: min_vouching_depth > 0 not supported until \
                 the vouching log lands (post-Phase 1)"
                    .to_string(),
            );
        }
    }
    let cfg = crate::community_voting_approval::Tier1PollConfig {
        options,
        window_seconds,
        quorum,
        threshold_percent,
        multi_winner,
        eligibility: crate::community_voting_core::Eligibility {
            min_power,
            min_vouching_depth,
            sortition_size: None,
        },
        channel_id,
    };
    crate::community_voting_approval::validate_poll_config(&cfg)
        .map_err(|e| format!("voting_create_tier1_poll: invalid config: {e:?}"))?;
    Ok(cfg)
}

