    #[test]
    fn list_pending_dm_invites_inner_projects_and_hides_secret_material() {
        use crate::pending_dm_invites::{PendingDmInvites, StagedDmInvite};
        let store = PendingDmInvites::new();
        let signed = crate::dm_envelope::test_fixtures::minimal_invite_for_space(0x11);
        assert!(store.stage(StagedDmInvite {
            signed: signed.clone(),
            received_at_ms: 4_242,
            refresh_owner_device_cache: true,
            source_cid: None,
        }));

        let rows = list_pending_dm_invites_inner(&store);
        assert_eq!(rows.len(), 1);
        let row = &rows[0];
        assert_eq!(row.space_id_hex, hex::encode(signed.space_id.0));
        assert_eq!(row.inviter_owner_id_hex, hex::encode(signed.inviter.0));
        assert_eq!(row.kind, signed.kind);
        assert_eq!(
            row.member_owner_ids_hex,
            signed
                .members
                .iter()
                .map(|m| hex::encode(m.0))
                .collect::<Vec<_>>()
        );
        assert_eq!(row.created_at_ms, signed.created_at.wall_ms);
        assert_eq!(row.received_at_ms, 4_242);

        // Pin the no-secret-material property: EXACTLY the six camelCase keys —
        // never `contentKey` / `inviterIdentityPub`.
        let json = serde_json::to_value(row).expect("serialize DTO");
        let obj = json.as_object().expect("DTO serializes to a JSON object");
        let mut keys: Vec<&str> = obj.keys().map(|k| k.as_str()).collect();
        keys.sort_unstable();
        assert_eq!(
            keys,
            vec![
                "createdAtMs",
                "inviterOwnerIdHex",
                "kind",
                "memberOwnerIdsHex",
                "receivedAtMs",
                "spaceIdHex",
            ],
            "DTO must expose exactly the six routing/display keys (no trust-secret material)"
        );
    }

    #[test]
    fn list_pending_dm_invites_inner_sorts_by_received_at_and_empty_is_empty() {
        use crate::pending_dm_invites::{PendingDmInvites, StagedDmInvite};
        let store = PendingDmInvites::new();
        assert!(list_pending_dm_invites_inner(&store).is_empty());
        // Stage out of order — the projector must return them by received_at_ms.
        // 0x24/0x22 share a millisecond: the space_id_hex tie-breaker must keep
        // their relative order deterministic regardless of HashMap iteration.
        for (space, ms) in [
            (0x24u8, 3_000u64),
            (0x22, 3_000),
            (0x21, 1_000),
            (0x23, 2_000),
        ] {
            assert!(store.stage(StagedDmInvite {
                signed: crate::dm_envelope::test_fixtures::minimal_invite_for_space(space),
                received_at_ms: ms,
                refresh_owner_device_cache: false,
                source_cid: None,
            }));
        }
        let order: Vec<(u64, String)> = list_pending_dm_invites_inner(&store)
            .iter()
            .map(|r| (r.received_at_ms, r.space_id_hex.clone()))
            .collect();
        assert_eq!(
            order.iter().map(|(ms, _)| *ms).collect::<Vec<_>>(),
            vec![1_000, 2_000, 3_000, 3_000],
            "sorted by received_at_ms"
        );
        assert!(
            order[2].1 < order[3].1,
            "same-ms invites tie-break on space_id_hex ({} !< {})",
            order[2].1,
            order[3].1
        );
    }

    // ── ZEB-640 (2): permanent accept failures drop the pending row ──────

    /// A space tombstoned between staging and the user's Accept click is a
    /// deterministic-permanent CRDT reject (same input, same reject — pure
    /// function of state + input). Re-staging it would wedge the row: every
    /// Accept re-errors forever and only Decline clears it. The impl must
    /// DROP the row, refresh both UI surfaces, and return a distinct
    /// user-explainable error instead of the generic "accept failed".
    #[tokio::test]
    async fn accept_of_tombstoned_space_drops_pending_row_with_distinct_error() {
        use crate::pending_dm_invites::{PendingDmInvites, StagedDmInvite};

        let mut signed = crate::dm_envelope::test_fixtures::minimal_invite_for_space(0x2F);
        // The fixture carries a single member; a Dm Space must have exactly 2
        // distinct members and `apply_space` checks invariants BEFORE the
        // tombstone gate. Add the local side so the TOMBSTONE is what rejects
        // (accept does not re-verify signatures, so mutating here is sound).
        signed.members.push(OwnerAddr([0x30; 16]));
        let space_id = signed.space_id;
        let space_id_hex = hex::encode(space_id.0);

        let store = Arc::new(PendingDmInvites::new());
        assert!(store.stage(StagedDmInvite {
            signed,
            received_at_ms: 1_000,
            refresh_owner_device_cache: false,
            source_cid: None,
        }));

        // Tombstone AFTER staging — the ZEB-640 wedge window: the space died
        // between the invite being staged and the user clicking Accept.
        let mut owner_state = OwnerState::default();
        owner_state.tombstone_space(space_id);

        let state = std::sync::Mutex::new(NodeState {
            pending_dm_invites: Some(Arc::clone(&store)),
            crdt_state: Some(Arc::new(TokioMutex::new(owner_state))),
            dm_device_id: Some("dev".into()),
            ..NodeState::default()
        });
        let rec = crate::node_event_sink::RecordingSink::new();
        let sink: Arc<dyn crate::node_event_sink::NodeEventSink> = Arc::new(Arc::clone(&rec));

        // (a) Distinct, user-explainable error — not the generic
        // "accept failed" used by the (defensive) transient arm.
        let err = accept_dm_invite_impl(&state, Arc::clone(&sink), space_id_hex.clone())
            .await
            .expect_err("accept of a tombstoned space must error");
        assert!(
            err.starts_with("invite no longer applicable"),
            "permanent CRDT reject must return the distinct message, got: {err}"
        );

        // (b) The row is DROPPED, not re-staged — no wedge.
        assert!(
            list_pending_dm_invites_inner(&store).is_empty(),
            "a permanent reject must drop the pending row, not re-stage it"
        );

        // (c) Exactly one dm-invite-list-changed so both UI surfaces (inbox
        // panel + badge) drop the dead row.
        let changed = rec
            .frames()
            .iter()
            .filter(|(event, _)| event == "dm-invite-list-changed")
            .count();
        assert_eq!(
            changed, 1,
            "exactly one dm-invite-list-changed must be emitted on drop"
        );

        // (d) The row is really gone: a second Accept hits the standard
        // missing-row guard, not another CRDT reject.
        let err2 = accept_dm_invite_impl(&state, sink, space_id_hex)
            .await
            .expect_err("second accept must fail: the row is gone");
        assert!(
            err2.contains("no pending DM invite for space"),
            "second accept must hit the no-row guard, got: {err2}"
        );
    }

    #[test]
    fn accept_marks_approved_so_next_dial_is_inline() {
        // The accept IPC's effect: mark_approved → the acceptor's `is_approved`
        // (which it consults for `prior_accept`) now returns true, so the
        // requester's next dial is accepted inline.
        use crate::friend_requests::PendingFriendRequests;
        let store = PendingFriendRequests::new();
        let addr = OwnerAddr([0xC3; 16]);
        store.record_inbound(addr, Some("carol".into()), 5_000);
        assert!(!store.is_approved(&addr), "not approved before accept");
        store.mark_approved(addr);
        assert!(
            store.is_approved(&addr),
            "after accept, the requester is approved (prior_accept gate opens)"
        );
    }

    #[test]
    fn decline_drops_inbound_and_approval() {
        use crate::friend_requests::PendingFriendRequests;
        let store = PendingFriendRequests::new();
        let addr = OwnerAddr([0xD4; 16]);
        store.record_inbound(addr, None, 6_000);
        store.mark_approved(addr);
        store.decline(&addr);
        assert!(
            list_pending_friend_requests_inner(&store, 0).is_empty(),
            "decline drops the inbound request"
        );
        assert!(!store.is_approved(&addr), "decline drops the approval too");
    }

    #[test]
    fn decode_owner_id_16_roundtrips_and_rejects_bad_len() {
        let addr = OwnerAddr([0x5A; 16]);
        let hexed = hex::encode(addr.0);
        assert_eq!(super::decode_owner_id_16(&hexed).expect("decode"), addr);
        // 15 bytes → wrong length.
        let short = hex::encode([0u8; 15]);
        assert!(super::decode_owner_id_16(&short).is_err());
        // not hex.
        assert!(super::decode_owner_id_16("zz").is_err());
    }

    #[test]
    fn decode_id_16_prechecks_length_before_decoding() {
        // Canonical happy path: 32 hex chars → the 16 decoded bytes.
        let ok = "ab".repeat(16);
        assert_eq!(
            super::decode_id_16(&ok, "space_id").expect("decode"),
            [0xAB; 16]
        );
        // Oversized, attacker-controlled input is rejected by the cheap length
        // precheck — the message is the LENGTH error, not a hex-parse error,
        // which proves control never reached `hex::decode_to_slice` (so no
        // input-proportional allocation happened). ZEB-886.
        let huge = "ab".repeat(8192);
        let err = super::decode_id_16(&huge, "space_id").unwrap_err();
        assert!(
            err.contains("space_id must be 16 bytes"),
            "oversized input must fail the precheck, got: {err}"
        );
        // Odd-length (31 chars) is a length failure, not an odd-digit hex failure.
        let odd = "a".repeat(31);
        assert!(super::decode_id_16(&odd, "space_id")
            .unwrap_err()
            .contains("must be 16 bytes"));
        // Correct length but non-hex → decode error (precheck passed, decode ran).
        let nonhex = "zz".repeat(16);
        assert!(super::decode_id_16(&nonhex, "space_id")
            .unwrap_err()
            .contains("invalid space_id hex"));
        // The `field` label is threaded into the error messages.
        assert!(super::decode_id_16("", "owner_id")
            .unwrap_err()
            .contains("owner_id must be 16 bytes"));
    }

    #[test]
    fn classify_pending_outcome_is_pending() {
        // The Path-A `Pending` reply MUST classify as `AddFriendOutcome::Pending`
        // (no FriendEntry written — the caller retries after the target accepts).
        assert_eq!(super::classify_pending_outcome(), AddFriendOutcome::Pending);
    }

    #[test]
    fn transient_relay_warmup_error_classifies_as_unreachable() {
        // ZEB-415 #3: during pkarr relay warm-up (~1–2 min after start) and after
        // idle/sleep, every relay is on cooldown and `resolve_window` returns this
        // raw error. It is NOT a hard fault — a retry moments later succeeds — so
        // `add_friend_by_key` must surface it as the graceful `Unreachable`
        // outcome, not leak the raw string to the UI.
        assert!(super::resolve_error_is_transient_unreachable(
            "no relays available (all on cooldown or unreachable)"
        ));
        // The distinctive substring is enough — wording around it may gain detail.
        assert!(super::resolve_error_is_transient_unreachable(
            "pkarr: no relays available right now"
        ));
        // Genuine resolve faults are NOT transient — they must still surface as
        // `Err` so the user sees a real diagnostic rather than a misleading
        // "couldn't reach them".
        assert!(!super::resolve_error_is_transient_unreachable(
            "dht query timed out"
        ));
        assert!(!super::resolve_error_is_transient_unreachable(
            "decode routing_blob: malformed cbor"
        ));
        assert!(!super::resolve_error_is_transient_unreachable(""));
    }

